import { useState } from "react";
import { useNavigate } from "react-router-dom";

/* COLORS */
const C = {
  black: "#0a0a0a",
  white: "#ffffff",
  gold: "#c9a84c",
  gray200: "#e0dbd2",
  gray400: "#9b9690",
  red: "#c0392b",
};

/* INPUT STYLE */
const inputStyle = (focus) => ({
  width: "100%",
  height: "48px",
  padding: "0 14px",
  border: `1.5px solid ${focus ? C.gold : C.gray200}`,
  borderRadius: "8px",
  outline: "none",
});

export default function Login() {
  const navigate = useNavigate(); // ✅ IMPORTANT

  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const [focusId, setFocusId] = useState(false);
  const [focusPw, setFocusPw] = useState(false);

  const handleLogin = () => {
    setError("");

    // ✅ Validation
    if (!identifier.trim()) {
      setError("Email or Phone is required");
      return;
    }

    if (!password.trim()) {
      setError("Password is required");
      return;
    }

    setLoading(true);

    setTimeout(() => {
      setLoading(false);

      // ✅ SUCCESS → Redirect to Home
      navigate("/home");

    }, 1000);
  };

  return (
    <div className="main-container">

      {/* LEFT PANEL */}
      <div className="login-left">
        <h2 className="logo">
          The<span>Zuro</span>
        </h2>
        <p className="tagline">
          Join India's fastest growing shopping platform 🚀
        </p>
      </div>

      {/* RIGHT PANEL */}
      <div className="login-right">
        <div className="form-container">

          <h2>Welcome Back 👋</h2>

          {error && <div className="error">{error}</div>}

          {/* INPUT */}
          <input
            style={inputStyle(focusId)}
            placeholder="Email or Phone"
            value={identifier}
            onChange={(e) => setIdentifier(e.target.value)}
            onFocus={() => setFocusId(true)}
            onBlur={() => setFocusId(false)}
          />

          {/* PASSWORD */}
          <div className="password-box">
            <input
              style={inputStyle(focusPw)}
              type={showPw ? "text" : "password"}
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              onFocus={() => setFocusPw(true)}
              onBlur={() => setFocusPw(false)}
            />
            <span onClick={() => setShowPw(!showPw)}>👁</span>
          </div>

          {/* BUTTON */}
          <button onClick={handleLogin}>
            {loading ? "Loading..." : "Login"}
          </button>

        </div>
      </div>

      {/* CSS */}
      <style>{`

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: Arial;
}

html, body {
  width: 100%;
  height: 100%;
  overflow-x: hidden;
}

/* MOBILE FIRST */
.main-container {
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
}

/* LEFT HIDDEN MOBILE */
.login-left {
  display: none;
}

/* RIGHT */
.login-right {
  width: 100%;
  padding: 20px;
}

/* FORM */
.form-container {
  width: 100%;
}

/* INPUT */
input {
  width: 100%;
  height: 48px;
  margin-bottom: 14px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid #ddd;
}

/* PASSWORD */
.password-box {
  position: relative;
}

.password-box span {
  position: absolute;
  right: 10px;
  top: 12px;
  cursor: pointer;
}

/* BUTTON */
button {
  width: 100%;
  height: 48px;
  background: black;
  color: white;
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

/* ERROR */
.error {
  color: red;
  margin-bottom: 10px;
}

/* DESKTOP */
@media (min-width: 768px) {

  .main-container {
    flex-direction: row;
  }

  .login-left {
    display: flex;
    flex: 1;
    background: black;
    color: white;
    padding: 60px;
    flex-direction: column;
    justify-content: center;
  }

  .logo span {
    color: ${C.gold};
  }

  .login-right {
    max-width: 500px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 40px;
  }

  .form-container {
    max-width: 380px;
  }
}

      `}</style>
    </div>
  );
}
